-- 005d READINESS AUDIT — FAQAT SELECT (staging'da ham, production'da ham xavfsiz; hech narsani o'zgartirmaydi).
-- Bitta JSON qator qaytaradi: FK, trigger, funksiya huquqlari, RPC guard'lari, RLS, ma'lumot holati.
with
tgt(con) as (values ('profiles_id_fkey'),('docs_owner_fkey'),('exam_attempts_user_id_fkey'),('certificates_user_id_fkey'),('attempt_resets_user_id_fkey'),('exam_configs_course_id_fkey')),
fk as (select c.conname, c.confdeltype::text t from pg_constraint c join tgt on tgt.con = c.conname where c.contype = 'f'),
fn as (select p.oid, p.proname, pg_get_function_result(p.oid) r, p.prosecdef d from pg_proc p where p.pronamespace = 'public'::regnamespace and p.prokind = 'f'),
cat(name, c) as (values ('verify_certificate','public_safe'),('start_exam','employee_rpc'),('save_answers','employee_rpc'),('submit_exam','employee_rpc'),('get_attempt_review','employee_rpc'),('question_meta','employee_rpc'),
  ('admin_reset_attempts','role_rpc'),('revoke_certificate','role_rpc'),('import_research_result','role_rpc'),('set_employee_status','role_rpc'),
  ('my_org','rls_helper'),('my_role','rls_helper'),('my_dept','rls_helper'),('my_department_id','rls_helper'),('my_employee_id','rls_helper'),('has_perm','rls_helper'),
  ('is_course_instructor','rls_helper'),('can_see_question','rls_helper'),('can_see_question_row','rls_helper'),('can_see_source','rls_helper'),
  ('_attempt_out','internal'),('_attempt_payload','internal'),('_cert_out','internal'),('_default_evidence_tier','internal'),('_grade','internal'),('_norm','internal'),('_q_at','internal'),
  ('_q_exam_eligible','internal'),('_q_full','internal'),('_q_is_clinical','internal'),('_q_public','internal'),('_q_refs','internal'),('_safe_date','internal'),
  ('guard_evidence_classification_origin_ok','internal'),('is_api_request','internal'),('mark_overdue_assignments','internal'),('recompute_question_evidence','internal'),
  ('refresh_evidence_freshness','internal'),('seed_org_defaults','internal'),('seed_org_defaults_005','internal')),
fc as (select fn.*, coalesce(cat.c, case when fn.r in ('trigger','event_trigger') then 'trigger' end) c from fn left join cat on cat.name = fn.proname),
ses as (select prosrc s from pg_proc where proname = 'set_employee_status' and pronamespace = 'public'::regnamespace),
vc as (select prosrc s from pg_proc where proname = 'verify_certificate' and pronamespace = 'public'::regnamespace)
select jsonb_build_object(
  'project_marker', (select string_agg(split_part(email, '@', 2), ',' order by 1) from (select distinct email from auth.users limit 3) x),
  'migrations', (select string_agg(version, ',' order by version) from public.schema_migrations),
  'fk_target', (select jsonb_object_agg(conname, t) from fk),
  'cascade_public_all', (select count(*) from pg_constraint where contype = 'f' and confdeltype = 'c' and connamespace = 'public'::regnamespace),
  'functions', (select count(*) from fn), 'definer', (select count(*) from fn where d),
  'anon_exec', (select count(*) from fn where has_function_privilege('anon', oid, 'execute')),
  'anon_exec_names', (select coalesce(string_agg(proname, ',' order by proname), '-') from fn where has_function_privilege('anon', oid, 'execute') and (select count(*) from fn f where has_function_privilege('anon', f.oid, 'execute')) <= 3),
  'auth_exec_internal_or_trigger', (select coalesce(string_agg(proname, ','), '-') from fc where c in ('internal','trigger') and has_function_privilege('authenticated', oid, 'execute')),
  'auth_missing_required', (select coalesce(string_agg(proname, ','), '-') from fc where c in ('employee_rpc','role_rpc','rls_helper','public_safe') and not has_function_privilege('authenticated', oid, 'execute')),
  'unclassified', (select coalesce(string_agg(proname, ','), '-') from fc where c is null),
  'triggers_005d', (select coalesce(string_agg(tgname || ':' || tgrelid::regclass::text || ':' || case when tgtype & 8 = 8 then 'D' else '' end || case when tgtype & 16 = 16 then 'U' else '' end, ','), '-') from pg_trigger where tgname in ('certificates_history_guard_trg','exam_attempts_history_guard_trg')),
  'set_employee_status_guards', (select jsonb_build_object('reason', s like '%sababi kiritilishi shart%', 'self', s like '%O''''z akkauntingiz%' or s like '%z akkauntingiz%', 'hr_vs_sa', s like '%Super Admin holatini faqat Super Admin%',
      'reactivate_sa_only', s like '%faqat Super Admin qayta faollashtira%', 'org', s like '%org_id = v_org%', 'last_sa', s like '%Oxirgi faol Super Admin%', 'audit', s like '%insert into public.audit_logs%') from ses),
  'verify_certificate_fields', (select regexp_replace(substring(s from 'jsonb_build_object\((.*)\)\s*from'), '\s+', ' ', 'g') from vc),
  'profiles_status_chk', (select pg_get_constraintdef(oid) from pg_constraint where conrelid = 'public.profiles'::regclass and conname = 'profiles_status_check'),
  'profile_statuses', (select jsonb_object_agg(status, n) from (select status, count(*) n from public.profiles group by status) x),
  'policies', (select count(*) from pg_policies where schemaname = 'public'),
  'tables_without_rls', (select coalesce(string_agg(relname, ','), '-') from pg_class where relnamespace = 'public'::regnamespace and relkind = 'r' and not relrowsecurity),
  'delete_policies', (select coalesce(string_agg(tablename, ',' order by tablename), '-') from pg_policies where schemaname = 'public' and cmd in ('DELETE','ALL')),
  'anon_table_select', (select coalesce(string_agg(table_name, ','), '-') from information_schema.role_table_grants where table_schema = 'public' and grantee = 'anon' and privilege_type = 'SELECT'),
  'rls_auto_enable', (select count(*) from fn where proname = 'rls_auto_enable'),
  'default_acl_public_fn', (select coalesce(string_agg(defaclrole::regrole::text || '=' || defaclacl::text, ' ; '), '-') from pg_default_acl where defaclnamespace = 'public'::regnamespace and defaclobjtype = 'f'),
  'backup_pre005d', to_regclass('backup.tables_pre005d_20261123') is not null, 'snapshot_security_pre005d', to_regclass('backup.security_pre005d') is not null,
  'counts', jsonb_build_object('questions', (select count(*) from public.questions), 'attempts', (select count(*) from public.exam_attempts), 'finished_attempts', (select count(*) from public.exam_attempts where finished_at is not null),
     'certificates', (select count(*) from public.certificates), 'profiles', (select count(*) from public.profiles), 'employees', (select count(*) from public.employees), 'docs', (select count(*) from public.docs),
     'eligible', (select count(*) from public.questions q where public._q_exam_eligible(q)))
)::text as audit;
